void main() {
    DiscordRPC.initialize();
    runApp(MyApp());
}

DiscordRPC rpc = DiscordRPC(
    applicationId: 'APPLICATION_ID',
);

rpc.start(autoRegister: true);
rpc.updatePresence(
    DiscordPresence(
        state: 'Discord Rich Presence from Dart. 🎯',
        details: 'github.com/alexmercerind/dart_discord_rpc',
    ),
);
